const parseApiResponse=async(r:Response,startedAt:number)=>{
 const elapsed=Math.max(1,Math.round(performance.now()-startedAt));
 const workerMsHeader=r.headers.get('X-Worker-Ms');
 const ms=workerMsHeader?Number(workerMsHeader):elapsed;
 const text=await r.text();
 let j:any=null;
 try{j=JSON.parse(text);}catch{}
 if(!j){
  const is1102=r.status>=500||/1102|exceeded|resource limits|cpu time/i.test(text);
  if(is1102){
   setServerStatus({state:'overload',ms,cooldown:6});
   throw Error(language==='VI'?'Máy chủ Cloudflare vừa chạm giới hạn CPU/RAM (Error 1102). Hãy dừng thao tác 6 giây cho hệ thống ổn định rồi bấm thử lại.':'Cloudflare Worker hit its CPU/RAM limit (Error 1102). Pause 6 seconds and retry.');
  }
  setServerStatus({state:'expired',ms,cooldown:0});
  throw Error(language==='VI'?'Phiên đăng nhập Cloudflare Access đã hết hạn hoặc bị gián đoạn. Hãy nhấn F5 tải lại trang để xác thực lại.':'Cloudflare Access session expired or interrupted. Press F5 to reload and sign in again.');
 }
 if(!r.ok){
  setServerStatus(s=>({state:ms>1200?'warn':'ok',ms,cooldown:s.cooldown}));
  throw Error(j.error||'Request failed');
 }
 setServerStatus({state:ms>1200?'warn':'ok',ms,cooldown:0});
 return j;
};
const pingRunning=useRef(false);
const pingServer=async()=>{
 if(pingRunning.current||actionLock.current||saveRunning.current||reuseRunning.current)return;
 pingRunning.current=true;
 const startedAt=performance.now();
 try{
  const r=await fetch('/api/workspace?ping=1',{cache:'no-store'});
  const ms=Math.max(1,Math.round(performance.now()-startedAt));
  const text=await r.text();
  let j:any=null;try{j=JSON.parse(text);}catch{}
  if(!j){
   const is1102=r.status>=500||/1102|exceeded|resource limits|cpu time/i.test(text);
   setServerStatus(s=>s.cooldown>0?s:(is1102?{state:'overload',ms,cooldown:6}:{state:'expired',ms,cooldown:0}));
   return;
  }
  if(!r.ok){setServerStatus(s=>s.cooldown>0?s:{state:'warn',ms,cooldown:0});return;}
  setServerStatus(s=>s.cooldown>0?s:{state:ms>1200?'warn':'ok',ms,cooldown:0});
 }catch{
  setServerStatus(s=>s.cooldown>0?s:{state:'warn',ms:s.ms,cooldown:0});
 }finally{pingRunning.current=false;}
};
