function chooseCoverage(item:any,version:any,image:any=null,defaultMonth=''){
 const existingPoIds=Array.isArray(image?.poIds)?[...image.poIds]:[];
 const perSku=image?isPerSkuImage(items,item.destination,item.list_no,version.item_code):false;
 const initialMonths=image&&image.months?.length?[...image.months]:(image&&defaultMonth?[defaultMonth]:[...(image?image.months:version.months)]);
 setDialog({
  type:'coverage',
  itemId:item.id,
  versionId:version.id,
  imageId:image?.id,
  imageName:image?.name,
  months:initialMonths,
  poScope:existingPoIds.length||perSku?'specific':'all',
  poIds:existingPoIds,
  poSearch:'',
  showAllCountries:false,
  all:image?false:!!version.all&&ws.months.every((m:any)=>version.months.includes(m.id))
 });
}
async function applyCoverage(){
 const d={...dialog,months:dialog.all&&!dialog.imageId?ws.months.map((m:any)=>m.id):dialog.months};
 const next=structuredClone(items);
 const m=next.find((a:any)=>a.id===d.itemId),v=m.versions.find((a:any)=>a.id===d.versionId);
 if(d.imageId){
  validateImageMonths(d.months,language);
  if(m.versions.length>1&&d.months.some((id:string)=>!v.months.includes(id)))throw Error(language==='VI'?'Hãy chọn tháng cho version trước.':'Select version months first');
  const activeMonth=d.months[0]||'';
  const perSku=isPerSkuImage(items,m.destination,m.list_no,v.item_code);
  const scope=perSku?'specific':d.poScope;
  const targetPoIds=activeMonth&&scope==='specific'?[...new Set<string>(d.poIds||[])]:[];
  if(activeMonth&&scope==='specific'&&!targetPoIds.length)throw Error(language==='VI'?'Vui lòng chọn ít nhất một SKU / PO cho hình này.':'Select at least one SKU / PO for this image.');
  for(const im of v.images){
   if(im.id===d.imageId){
    im.months=d.months;
    im.poIds=targetPoIds;
   }else if(activeMonth&&(im.months||[]).includes(activeMonth)){
    const otherPoIds=Array.isArray(im.poIds)?im.poIds:[];
    if(!targetPoIds.length){
     if(!otherPoIds.length){
      im.months=im.months.filter((id:string)=>id!==activeMonth);
      im.poIds=[];
     }
    }else if(otherPoIds.length){
     const remaining=otherPoIds.filter((id:string)=>!targetPoIds.includes(id));
     im.poIds=remaining;
     if(!remaining.length)im.months=im.months.filter((id:string)=>id!==activeMonth);
    }
   }
  }
  validateVersionImages(v.images,language);
 }else{
  validateVersionMonths(m,v.id,d.months,ws.months,language);
  v.months=d.months;
  v.all=!!d.all;
  for(const im of v.images)if(m.versions.length>1){
   im.months=im.months.filter((id:string)=>v.months.includes(id));
   if(!im.months.length)im.poIds=[];
  }
 }
 if(await saveItemApplication(next))setDialog(null);
}
