function BufferSummary({settings,items,month}:any){
 const groups=purchaseBufferSummary(settings,items,month);
 return groups.length?<div className="row wrap mt buffer-summary"><b>Buffer</b>{groups.map(g=><div className="buffer-summary-group" key={g.key}><span className="badge">{g.label}: <strong>{g.value}%</strong></span>{g.custom.map(r=><span className="badge buffer-summary-custom" key={r.country+'|'+r.no}>{r.country} · NO. {r.no}: <strong>{r.value}%</strong></span>)}</div>)}</div>:null;
}